document.getElementById('print-doc').addEventListener('click',()=>window.print());const links=[...document.querySelectorAll('aside a')];const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){links.forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-80px 0px -65% 0px',threshold:0});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));